            for (long c : cuts) sum += c;
            cuts[target] += potCents - sum;
        }
        Map<String, Long> out = new LinkedHashMap<>();
        for (int i = 0; i < members.size(); i++) out.put(members.get(i).key(), cuts[i]);
        return out;
    }

